import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  const weatherDefinition = {
    name: 'get_weather',
    description: 'Get weather for a location',
    inputSchema: {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    },
  };
  const registerWeatherTool = (registry: ToolRegistry, onExecute: () => void) => {
    registry.register(weatherDefinition, async () => {
      onExecute();
      return 'sunny';
    });
  };

  it('rejects input missing a required property and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registerWeatherTool(registry, () => executorCalls++);

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required|required.*location/i),
    });
  });

  it('rejects a wrong-typed property with its field path and expected type without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registerWeatherTool(registry, () => executorCalls++);

    const response = await registry.execute('get_weather', {location: 123456789});

    expect({
      executorCalls,
      namesField: response.result.includes('location'),
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({executorCalls: 0, namesField: true, namesExpectedType: true, leaksValue: false});
  });

  it('reports a nested invalid property path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', properties: {city: {type: 'string'}}}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('get_weather', {location: {city: 123456789}});

    expect(response.result).toMatch(/location\.city.*string/i);
  });

  it('names a root property when its value has the wrong type', async () => {
    const registry = new ToolRegistry();
    registerWeatherTool(registry, () => undefined);

    const response = await registry.execute('get_weather', {location: 123});

    expect(response.result).toMatch(/location.*string/i);
  });

  it('rejects a property value outside its declared enum', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {unit: 'kelvin'});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/unit.*enum|enum.*unit/i),
    });
  });

  it('reports the root property path from a type validation error', async () => {
    const registry = new ToolRegistry();
    registerWeatherTool(registry, () => undefined);

    const response = await registry.execute('get_weather', {location: 123});

    expect(response.result).toContain('location');
  });

  it('throws for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing-tool', {})).rejects.toThrow('Unknown tool: missing-tool');
  });

  it('passes valid input with undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(weatherDefinition, async input => {
      executorCalls += 1;
      receivedInput = input;
      return 'sunny';
    });
    const input = {location: 'Paris', unit: 'celsius'};

    await registry.execute('get_weather', input);

    expect({executorCalls, receivedInput}).toEqual({executorCalls: 1, receivedInput: input});
  });

  it('validates function-valued definitions against the schema returned for each call', async () => {
    let definitionVersion = 0;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic schema tool',
        inputSchema:
          definitionVersion++ < 2
            ? {type: 'object', properties: {first: {type: 'string'}}, required: ['first']}
            : {type: 'object', properties: {second: {type: 'string'}}, required: ['second']},
      }),
      async () => 'ok'
    );

    const firstResponse = await registry.execute('dynamic', {first: 'one'});
    const secondResponse = await registry.execute('dynamic', {first: 'one'});

    expect({firstResult: firstResponse.result, secondResult: secondResponse.result}).toEqual({
      firstResult: 'ok',
      secondResult: expect.stringMatching(/second.*required|required.*second/i),
    });
  });

  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      registerWeatherTool(registry, () => undefined);

      for (let call = 0; call < 10; call++) {
        await registry.execute('get_weather', {location: 'Paris'});
      }

      expect(compile).toHaveBeenCalledTimes(1);
    } finally {
      compile.mockRestore();
    }
  });
});
import type {ToolDefinition} from '../../types/ai.js';
import Ajv, {type ValidateFunction} from 'ajv';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

interface ValidationError {
  keyword: string;
  instancePath?: string;
  params: Record<string, unknown>;
}

function validationMessage(error?: ValidationError): string {
  if (!error) return 'Input does not match the tool inputSchema.';
  const instancePath = error.instancePath ?? (error as ValidationError & {dataPath?: string}).dataPath ?? '';
  const pathParts: string[] = instancePath.startsWith('/')
    ? instancePath
        .split('/')
        .filter(Boolean)
        .map((part: string) => part.replaceAll('~1', '/').replaceAll('~0', '~'))
    : (instancePath.match(/\.([^.[\]]+)|\[(?:"([^"]+)"|'([^']+)'|(\d+))\]/g) ?? []).map(part =>
        part.replace(/^\.|\[|\]|"|'/g, '')
      );
  const parentPath = pathParts.join('.');
  if (error.keyword === 'required') {
    const property = error.params.missingProperty as string;
    return `Input property "${[parentPath, property].filter(Boolean).join('.')}" is required.`;
  }
  const path = parentPath || 'input';
  if (error.keyword === 'type') {
    const expectedType = error.params.type as string;
    return `Input property "${path}" must be of type ${expectedType}.`;
  }
  return `Input property "${path}" violates the ${error.keyword} constraint.`;
}

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);
  private readonly schemaValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        staticValidator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool "${resolved.name}".`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns schema rejections; only an unknown tool name throws (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.getValidator(tool, definition);
    if (!validate(input)) {
      return {result: validationMessage(validate.errors?.[0] as ValidationError | undefined)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getValidator(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.staticValidator) return tool.staticValidator;
    const cached = this.schemaValidators.get(definition.inputSchema);
    if (cached) return cached;
    try {
      const compiled = this.ajv.compile(definition.inputSchema);
      this.schemaValidators.set(definition.inputSchema, compiled);
      return compiled;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool "${definition.name}".`, {cause: error});
    }
  }
}
